def transform(grid):
    out=[row[:] for row in grid]
    rs=[r for r,row in enumerate(grid) if 5 in row]
    cs=[c for c in range(len(grid[0])) if any(row[c]==5 for row in grid)]
    t,b,l,rr=min(rs),max(rs),min(cs),max(cs)
    # Each repeated motif is a framed 5 rectangle with its interior edge colored 2;
    # the demonstrative depth pattern recurs every 6 cells.
    vals=(2,5,0,5,2,0)
    for r in range(t+1,b):
        for c in range(l+1,rr):
            d=min(r-t,b-r,c-l,rr-c)
            out[r][c]=vals[(d-1)%6]
    return out
